import products from './products.json' with {type:'json'};

export async function listTools() {
  return [
    {
      name: 'inventory_search',
      description: 'Search products by name.',
      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string', description: 'Search query matched case-insensitively against product names.' },
          limit: { type: 'integer', minimum: 1, maximum: 10, description: 'Maximum number of results to return (1-10). Default 10.' }
        },
        required: ['query']
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'inventory_search') {
    throw new Error('Unknown tool: ' + name);
  }
  const { query, limit } = args;
  if (typeof query !== 'string') {
    throw new Error('query must be a string');
  }
  let effectiveLimit = 10;
  if (limit !== undefined) {
    if (typeof limit !== 'number' || !Number.isInteger(limit)) {
      throw new Error('limit must be an integer');
    }
    if (limit < 1 || limit > 10) {
      throw new Error('limit must be between 1 and 10');
    }
    effectiveLimit = limit;
  }
  const q = query.toLowerCase();
  const matches = products.filter(p => p.name.toLowerCase().includes(q)).slice(0, effectiveLimit);
  const text = matches.length
    ? matches.map(p => `${p.id}: ${p.name}`).join('\n')
    : 'No products found';
  return { content: [{ type: 'text', text }] };
}
